export interface Schema {
  fields: Record<string, string>;
}

export function generate(schema: Schema): string {
  const names = Object.keys(schema.fields);
  const props = names.map((n) => `  ${n}: ${schema.fields[n]};`).join("\n");
  return [
    "// GENERATED by scripts/codegen.ts from schema/user.json. Do not edit.",
    "export interface User {",
    props,
    "}",
    `export const USER_FIELDS = [${names.map((n) => JSON.stringify(n)).join(", ")}] as const;`,
    "",
  ].join("\n");
}

if (import.meta.main) {
  const schema: Schema = await Bun.file("schema/user.json").json();
  await Bun.write("src/generated/user.ts", generate(schema));
  console.log("generated src/generated/user.ts");
}
